ref/megatron_ref.yaml.text:
# megatron ref config, inheriting from trainer/config/ref/ref.yaml
defaults:
  - ref

  # megatron engine config
  - ../engine@megatron: megatron

  # load the reference default config, then apply the fields in the current yaml
  - _self_

_target_: verl.workers.config.McoreActorConfig

strategy: megatron

# Keep ref entropy chunking aligned with actor
entropy_from_logits_with_chunking: ${oc.select:actor_rollout_ref.actor.entropy_from_logits_with_chunking,False}
entropy_from_logits_chunk_size: ${oc.select:actor_rollout_ref.actor.entropy_from_logits_chunk_size,2048}

megatron:
  entropy_from_logits_with_chunking: ${oc.select:actor_rollout_ref.actor.entropy_from_logits_with_chunking,False}
  entropy_from_logits_chunk_size: ${oc.select:actor_rollout_ref.actor.entropy_from_logits_chunk_size,2048}
  seed: ${oc.select:actor_rollout_ref.actor.megatron.seed,42}
  override_transformer_config: ${oc.select:actor_rollout_ref.actor.megatron.override_transformer_config,{}}
  use_mbridge: ${oc.select:actor_rollout_ref.actor.megatron.use_mbridge,False}
  vanilla_mbridge: ${oc.select:actor_rollout_ref.actor.megatron.vanilla_mbridge,False}
  use_remove_padding: ${oc.select:actor_rollout_ref.actor.megatron.use_remove_padding,True}
  pad_to_length: ${oc.select:actor_rollout_ref.actor.megatron.pad_to_length,False}
  pad_to_length_bucket: ${oc.select:actor_rollout_ref.actor.megatron.pad_to_length_bucket,512}
  tensor_model_parallel_size: ${oc.select:actor_rollout_ref.actor.megatron.tensor_model_parallel_size,1}
  pipeline_model_parallel_size: ${oc.select:actor_rollout_ref.actor.megatron.pipeline_model_parallel_size,1}
  virtual_pipeline_model_parallel_size: ${oc.select:actor_rollout_ref.actor.megatron.virtual_pipeline_model_parallel_size,null}
  context_parallel_size: ${oc.select:actor_rollout_ref.actor.megatron.context_parallel_size,1}
  # Dynamic CP changes how Megatron process groups are initialized, so a
  # colocated reference model must follow the actor's setting.
  dynamic_context_parallel: ${oc.select:actor_rollout_ref.actor.megatron.dynamic_context_parallel,False}
  max_seqlen_per_dp_cp_rank: ${oc.select:actor_rollout_ref.actor.megatron.max_seqlen_per_dp_cp_rank,null}
  expert_model_parallel_size: ${oc.select:actor_rollout_ref.actor.megatron.expert_model_parallel_size,1}
  expert_tensor_parallel_size: ${oc.select:actor_rollout_ref.actor.megatron.expert_tensor_parallel_size,null}
  param_offload: ${oc.select:actor_rollout_ref.actor.megatron.param_offload,False}
  forward_only: True

ref/mindspeed_ref.yaml.text:
# mindspeed ref config, inheriting from trainer/config/ref/ref.yaml
