_target_: verl.workers.config.MindSpeedActorConfig

strategy: mindspeed

mindspeed:
  seed: ${oc.select:actor_rollout_ref.actor.mindspeed.seed,42}
  override_transformer_config: ${oc.select:actor_rollout_ref.actor.mindspeed.override_transformer_config,{}}
  use_mbridge: ${oc.select:actor_rollout_ref.actor.mindspeed.use_mbridge,False}
  vanilla_mbridge: ${oc.select:actor_rollout_ref.actor.mindspeed.vanilla_mbridge,True}
  use_remove_padding: ${oc.select:actor_rollout_ref.actor.mindspeed.use_remove_padding,True}
  tensor_model_parallel_size: ${oc.select:actor_rollout_ref.actor.mindspeed.tensor_model_parallel_size,1}
  pipeline_model_parallel_size: ${oc.select:actor_rollout_ref.actor.mindspeed.pipeline_model_parallel_size,1}
  virtual_pipeline_model_parallel_size: ${oc.select:actor_rollout_ref.actor.mindspeed.virtual_pipeline_model_parallel_size,null}
  context_parallel_size: ${oc.select:actor_rollout_ref.actor.mindspeed.context_parallel_size,1}
  expert_model_parallel_size: ${oc.select:actor_rollout_ref.actor.mindspeed.expert_model_parallel_size,1}
  expert_tensor_parallel_size: ${oc.select:actor_rollout_ref.actor.mindspeed.expert_tensor_parallel_size,null}
  param_offload: ${oc.select:actor_rollout_ref.actor.mindspeed.param_offload,False}
  forward_only: True
  strategy: ${oc.select:actor_rollout_ref.actor.mindspeed.strategy,''}
  mcore_kwargs: ${oc.select:actor_rollout_ref.actor.mindspeed.mcore_kwargs,{}}
  fsdp_kwargs: ${oc.select:actor_rollout_ref.actor.mindspeed.fsdp_kwargs,{}}

ref/torchtitan_ref.yaml.text:
# torchtitan ref config, inheriting from trainer/config/ref/ref.yaml
defaults:
  # torchtitan optimizer config
  - ../optim@optim: torchtitan

  # torchtitan engine config
  - ../engine@torchtitan: torchtitan

  - ref

  # load the reference default config, then apply the fields in the current yaml
  - _self_

_target_: verl.workers.config.TorchTitanActorConfig

strategy: torchtitan

torchtitan:
  seed: ${oc.select:actor_rollout_ref.actor.torchtitan.seed,42}
  data_parallel_size: ${oc.select:actor_rollout_ref.actor.torchtitan.data_parallel_size,1}
  data_parallel_replicate_size: ${oc.select:actor_rollout_ref.actor.torchtitan.data_parallel_replicate_size,1}
  data_parallel_shard_size: ${oc.select:actor_rollout_ref.actor.torchtitan.data_parallel_shard_size,1}
  tensor_parallel_size: ${oc.select:actor_rollout_ref.actor.torchtitan.tensor_parallel_size,1}
  expert_parallel_size: ${oc.select:actor_rollout_ref.actor.torchtitan.expert_parallel_size,1}
  pipeline_parallel_size: ${oc.select:actor_rollout_ref.actor.torchtitan.pipeline_parallel_size,1}
  context_parallel_size: ${oc.select:actor_rollout_ref.actor.torchtitan.context_parallel_size,1}
  attn_type: ${oc.select:actor_rollout_ref.actor.torchtitan.attn_type,flex}
  forward_only: True

ref/veomni_ref.yaml.text:
# veomni ref config, inheriting from trainer/config/ref/ref.yaml
defaults:
  - ref

  # veomni engine config
  - ../engine@veomni: veomni

  # load the reference default config, then apply the fields in the current yaml
  - _self_

_target_: verl.workers.config.VeOmniActorConfig

strategy: veomni

# pad every packed micro-batch to a fixed token count, following the actor unless overridden
pad_to_length: ${oc.select:actor_rollout_ref.actor.pad_to_length,False}

veomni:
  seed: ${oc.select:actor_rollout_ref.actor.veomni.seed,42}
  fsdp_size: ${oc.select:actor_rollout_ref.actor.veomni.fsdp_size,-1}
  ulysses_parallel_size: ${oc.select:actor_rollout_ref.actor.veomni.ulysses_parallel_size,1}
  expert_parallel_size: ${oc.select:actor_rollout_ref.actor.veomni.expert_parallel_size,1}
  param_offload: ${oc.select:actor_rollout_ref.actor.veomni.param_offload,False}
  attn_implementation: ${oc.select:actor_rollout_ref.actor.veomni.attn_implementation,flash_attention_2}
  moe_implementation: ${oc.select:actor_rollout_ref.actor.veomni.moe_implementation,fused}
  cross_entropy_loss_implementation: ${oc.select:actor_rollout_ref.actor.veomni.cross_entropy_loss_implementation,eager}
  rms_norm_implementation: ${oc.select:actor_rollout_ref.actor.veomni.rms_norm_implementation,eager}
  swiglu_mlp_implementation: ${oc.select:actor_rollout_ref.actor.veomni.swiglu_mlp_implementation,eager}
  rotary_pos_emb_implementation: ${oc.select:actor_rollout_ref.actor.veomni.rotary_pos_emb_implementation,eager}
  load_balancing_loss_implementation: ${oc.select:actor_rollout_ref.actor.veomni.load_balancing_loss_implementation,eager}
  pad_to_length: ${oc.select:actor_rollout_ref.ref.pad_to_length,False}
  pad_to_length_bucket: ${oc.select:actor_rollout_ref.actor.veomni.pad_to_length_bucket,1024}
  forward_only: True
